      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00063",
        "explanation": "Doctor explains the clinical reasoning linking antibiotic bone cement loss, worsening wound drainage, and hyperglycemia to the need for emergency care, rather than waiting for a clinic callback.",
        "quote": "抗生素骨水泥掉了，伤口里的\"局部放药\"和支撑同时丢失"
      }
    ],
    "continuity_memory_focus": [
      {
        "event_id": "lite_evt_00063",
